const cotizacion = $input.item.json;
const ctx = $('Recibir Datos').item.json;
const precio = cotizacion?.data?.precio_total || cotizacion?.precio_total;
const d = ctx.datosRecolectados || {};
const idioma = ctx.idiomaConversacion || 'español';
const nombre = d.nombre_cliente ? `, ${d.nombre_cliente.split(' ')[0]}` : '';

let mensajeFinal;

if (precio) {
  // Build a complete standalone price message (do NOT rely on the AI message)
  if (idioma === 'inglés') {
    mensajeFinal = `Here is your estimate${nombre}! 🎉

📦 *${d.producto || 'Crate'}*
📐 Dimensions: ${d.medidas || '—'}"
🗓 Needed by: ${d.fecha || '—'}
🛡 Extra protection: ${d.proteccion_extra ? 'Yes' : 'No'}

💵 *Estimated price: $${precio} USD*
_This is an estimate based on the dimensions provided. The final price may vary depending on additional details._

Would you like a formal quote sent to your email?`;
  } else {
    mensajeFinal = `¡Aquí está tu estimado${nombre}! 🎉

📦 *${d.producto || 'Cajón'}*
📐 Medidas: ${d.medidas || '—'}"
🗓 Para: ${d.fecha || '—'}
🛡 Protección extra: ${d.proteccion_extra ? 'Sí' : 'No'}

💵 *Precio estimado: $${precio} USD*
_Este es un estimado basado en las dimensiones indicadas. El precio final puede variar según detalles adicionales._

¿Le gustaría que le enviemos la cotización formal a su correo?`;
  }
} else {
  // API failed to return price — use the AI message as fallback
  mensajeFinal = ctx.mensaje || (idioma === 'inglés'
    ? 'I have all your details. A specialist will send you the quote shortly.'
    : 'Ya tengo todos tus datos. Un especialista te enviará la cotización pronto.');
}

return [{ json: { ...ctx, mensaje: mensajeFinal, mensajeRespuesta: mensajeFinal, cotizadorEnviado: !!precio } }];

